<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Bouncing Ball Physics Playground</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  background-color: #1a1a2e;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  color: #eee;
}

#app {
  text-align: center;
}

h1 {
  font-size: 24px;
  margin-bottom: 16px;
  color: #e94560;
  text-shadow: 0 0 10px rgba(233, 69, 96, 0.3);
}

#controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 16px;
}

button {
  padding: 10px 24px;
  font-size: 14px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
  font-weight: 600;
}

#drop {
  background-color: #e94560;
  color: white;
}
#drop:hover {
  background-color: #ff6b81;
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(233, 69, 96, 0.4);
}

#play {
  background-color: #0f3460;
  color: white;
  border: 2px solid #e94560;
}
#play:hover {
  background-color: #1a5276;
  transform: translateY(-2px);
}

#clear {
  background-color: #333;
  color: white;
}
#clear:hover {
  background-color: #555;
  transform: translateY(-2px);
}

#sim {
  border: 3px solid #0f3460;
  border-radius: 12px;
  cursor: crosshair;
  display: block;
  margin: 0 auto;
  background-color: #16213e;
}

#info {
  margin-top: 12px;
  font-size: 13px;
  color: #aaa;
}
</style>
</head>
<body>
<div id="app">
  <h1>🎱 Bouncing Ball Physics</h1>
  <div id="controls">
    <button id="drop">Drop Ball</button>
    <button id="play">Play/Pause</button>
    <button id="clear">Clear All</button>
  </div>
  <canvas id="sim" width="600" height="400"></canvas>
  <div id="info">Click anywhere on the canvas to add a ball · Gravity is always active</div>
</div>

<script>
(function() {
  // ─── Canvas Setup ────────────────────────────────────────
  const canvas = document.getElementById('sim');
  const ctx = canvas.getContext('2d');
  const W = canvas.width;
  const H = canvas.height;

  window.sim = { w: W, h: H };

  // ─── Physics Constants ────────────────────────────────────
  const GRAVITY = 0.5;
  const FRICTION = 1 - 0.08;       // air resistance per step
  const BOUNCE = 0.75;             // restitution (energy loss on bounce)

  // ─── Ball State ────────────────────────────────────────────
  let balls = [];
  let isPlaying = true;

  function createBall(x, y, vx, vy, r) {
    return { x: x + Math.random() * 10 - 5, y: y + Math.random() * 10 - 5, vx: vx || (Math.random() > 0.5 ? 2 : -2), vy: vy || 0, r: r || 8 };
  }

  // ─── Physics Engine ────────────────────────────────────────
  function step(dt) {
    const subSteps = dt; // for stability

    for (let s = 0; s < subSteps; s++) {
      balls.forEach(ball => {
        ball.vy += GRAVITY * dt;
        ball.vx *= FRICTION;
        ball.vy *= FRICTION;

        ball.x += ball.vx * dt;
        ball.y += ball.vy * dt;

        // Floor collision
        if (ball.y + ball.r > H) {
          ball.y = H - ball.r;
          ball.vy = -ball.vy * BOUNCE;
        }
        // Ceiling collision
        else if (ball.y - ball.r < 0) {
          ball.y = ball.r;
          ball.vy = -ball.vy * BOUNCE;
        }

        // Right wall collision
        if (ball.x + ball.r > W) {
          ball.x = W - ball.r;
          ball.vx = -ball.vx * BOUNCE;
        }
        // Left wall collision
        else if (ball.x - ball.r < 0) {
          ball.x = ball.r;
          ball.vx = -ball.vx * BOUNCE;
        }

        // Prevent tunneling: clamp to bounds
        ball.x = Math.max(ball.r, Math.min(W - ball.r, ball.x));
        ball.y = Math.max(ball.r, Math.min(H - ball.r, ball.y));
      });
    }
  }

  // ─── Rendering ──────────────────────────────────────────────
  function draw() {
    ctx.clearRect(0, 0, W, H);

    balls.forEach(ball => {
      const gradient = ctx.createRadialGradient(
        ball.x - ball.r * 0.3, ball.y - ball.r * 0.3, ball.r * 0.1,
        ball.x, ball.y, ball.r
      );

      // Color based on ball index for variety
      const hue = (ball._hue || 200) % 360;
      gradient.addColorStop(0, `hsl(${hue}, 85%, 70%)`);
      gradient.addColorStop(1, `hsl(${hue}, 85%, 40%)`);

      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
      ctx.fillStyle = gradient;
      ctx.fill();

      // White highlight for "glossy" look
      ctx.beginPath();
      ctx.arc(
        ball.x - ball.r * 0.3, ball.y - ball.r * 0.3,
        ball.r * 0.25, 0, Math.PI * 2
      );
      ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
      ctx.fill();

      // Shadow on ground
      const shadowGrad = ctx.createLinearGradient(ball.x, ball.y + ball.r, ball.x, ball.y + ball.r + 10);
      shadowGrad.addColorStop(0, 'rgba(0,0,0,0.3)');
      shadowGrad.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.beginPath();
      ctx.arc(ball.x, ball.y + ball.r, ball.r * 0.8, Math.PI, 0);
      ctx.fillStyle = shadowGrad;
      ctx.fill();
    });

    // Ball count label
    ctx.font = '13px Segoe UI';
    ctx.fillStyle = '#aaa';
    ctx.textAlign = 'left';
    ctx.fillText(`Balls: ${balls.length}`, 12, 20);
  }

  function loop() {
    if (isPlaying) step();
    draw();
    requestAnimationFrame(loop);
  }

  // ─── API Methods ──────────────────────────────────────────────
  window.sim.balls = function() { return balls.map(b => ({ x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r })); };
  window.sim.addBall = function(x, y, vx, vy, r) {
    if (x === undefined) x = W / 2;
    if (y === undefined) y = H / 3;
    return balls.push(createBall(x, y, vx || 0, vy || 0, r)) - 1; // returns index
  };
  window.sim.clear = function() { balls = []; };
  window.sim.step = function(dt) { step(dt); draw(); };

  // ─── Event Listeners ────────────────────────────────────────
  document.getElementById('drop').addEventListener('click', () => {
    const hue = (balls.length * 47 + 200) % 360;
    balls.push({
      x: W / 2, y: H / 3,
      vx: Math.random() > 0.5 ? 3 : -3,
      vy: 0,
      r: 8 + Math.floor(Math.random() * 10),
      _hue: hue
    });
    draw();
  });

  document.getElementById('play').addEventListener('click', () => {
    isPlaying = !isPlaying;
    // Re-attach loop in case it was paused mid-frame
    if (isPlaying) requestAnimationFrame(loop);
  });

  document.getElementById('clear').addEventListener('click', window.sim.clear);

  canvas.addEventListener('click', (e) => {
    const rect = canvas.getBoundingClientRect();
    const scaleX = W / rect.width;
    const scaleY = H / rect.height;
    const x = (e.clientX - rect.left) * scaleX;
    const y = (e.clientY - rect.top) * scaleY;

    // Add ball with slight random velocity for fun
    balls.push({
      x: x + Math.random() * 6 - 3,
      y: y + Math.random() * 6 - 3,
      vx: (Math.random() > 0.5 ? 1 : -1) * (2 + Math.random() * 4),
      vy: 0,
      r: 8 + Math.floor(Math.random() * 14),
      _hue: (balls.length * 37 + 180) % 360
    });

    // Immediately step once to show the ball
    if (!isPlaying) { requestAnimationFrame(loop); }
    draw();
  });

  // ─── Initialization ────────────────────────────────────────
  window.sim.addBall(W / 2, H / 3, 0, 0, 12);
  loop();
})();
</script>
</body>
</html>
